insert into public.exercise_catalog
  (id, name, muscle_group, equipment, guide, steps, default_sets, gif_url, thumbnail_url, source)
values
('open-3293', 'archer pull up', '背', '自重', '首先，用正手握法悬挂在引体向上杆上，握距略宽于肩宽。 启动你的核心并将肩胛骨向下拉和向后拉。 当你站起来时，弯曲一只手臂并将肘部移向身体一侧，同时保持另一只手臂伸直。 继续拉，直到下巴位于杠铃上方并且弯曲的手臂完全弯曲。 有控制地放低自己，伸直弯曲的手臂并在另一侧重复该动作。 每次重复时交替进行。', '["首先，用正手握法悬挂在引体向上杆上，握距略宽于肩宽。","启动你的核心并将肩胛骨向下拉和向后拉。","当你站起来时，弯曲一只手臂并将肘部移向身体一侧，同时保持另一只手臂伸直。","继续拉，直到下巴位于杠铃上方并且弯曲的手臂完全弯曲。","有控制地放低自己，伸直弯曲的手臂并在另一侧重复该动作。","每次重复时交替进行。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3293-72BC5Za.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0017', 'assisted pull-up', '背', '器械', '将机器调整至您所需的体重和高度设置。 正手握住手柄，握距略宽于肩宽。 双臂完全伸展，双脚离开地面。 收紧背部肌肉，将身体拉向手柄，保持肘部靠近身体。 继续拉，直到下巴位于手柄上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。', '["将机器调整至您所需的体重和高度设置。","正手握住手柄，握距略宽于肩宽。","双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向手柄，保持肘部靠近身体。","继续拉，直到下巴位于手柄上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0017-kiJ4Z2K.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-3297', 'back lever', '背', '自重', '首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。 启动你的核心并将肩胛骨向下拉和向后拉。 弯曲膝盖并将其向胸部靠拢。 慢慢抬起双腿，保持伸直，直到身体与地面平行。 保持这个姿势几秒钟，然后慢慢地将双腿放回起始位置。 重复所需的重复次数。', '["首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。","启动你的核心并将肩胛骨向下拉和向后拉。","弯曲膝盖并将其向胸部靠拢。","慢慢抬起双腿，保持伸直，直到身体与地面平行。","保持这个姿势几秒钟，然后慢慢地将双腿放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3297-GaSzzuh.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-1405', 'back pec stretch', '背', '自重', '站直，双脚分开与肩同宽。 将双臂伸直在身前，与地面平行。 双臂交叉在身体前方，右臂放在左臂上方。 手指交叉，手掌旋转远离身体。 慢慢抬起手臂并远离身体，感觉背部和胸部有拉伸感。 保持拉伸 15-30 秒，然后放松。 在另一侧重复。', '["站直，双脚分开与肩同宽。","将双臂伸直在身前，与地面平行。","双臂交叉在身体前方，右臂放在左臂上方。","手指交叉，手掌旋转远离身体。","慢慢抬起手臂并远离身体，感觉背部和胸部有拉伸感。","保持拉伸 15-30 秒，然后放松。","在另一侧重复。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1405-chfnQnM.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0049', 'barbell incline row', '背', '杠铃', '设置一个 45 度角的上斜凳。 脸朝下躺在长凳上，胸部靠在垫子上，双脚平放在地上。 正手握住杠铃，握距略宽于肩宽。 保持背部挺直，核心肌群参与。 将杠铃拉向胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。', '["设置一个 45 度角的上斜凳。","脸朝下躺在长凳上，胸部靠在垫子上，双脚平放在地上。","正手握住杠铃，握距略宽于肩宽。","保持背部挺直，核心肌群参与。","将杠铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0049-dmgMp3n.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-3017', 'barbell pendlay row', '背', '杠铃', '双脚分开与肩同宽站立，膝盖稍微弯曲。 臀部向前弯曲，保持背部挺直，挺胸。 正手握住杠铃，握距略宽于肩宽。 将杠铃拉向上腹部，将肩胛骨挤压在一起。 将杠铃降低回到起始位置。 重复所需的重复次数。', '["双脚分开与肩同宽站立，膝盖稍微弯曲。","臀部向前弯曲，保持背部挺直，挺胸。","正手握住杠铃，握距略宽于肩宽。","将杠铃拉向上腹部，将肩胛骨挤压在一起。","将杠铃降低回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3017-r0z6xzQ.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0073', 'barbell pullover', '背', '杠铃', '平躺在长凳上，头放在一端，双脚放在地板上。 握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。 保持手臂伸直，以受控的方式将杠铃降低到头后，直到感觉到背阔肌被拉伸。 暂停片刻，然后将杠铃举回起始位置。 重复所需的重复次数。', '["平躺在长凳上，头放在一端，双脚放在地板上。","握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。","保持手臂伸直，以受控的方式将杠铃降低到头后，直到感觉到背阔肌被拉伸。","暂停片刻，然后将杠铃举回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0073-i6LWjok.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0095', 'barbell shrug', '背', '杠铃', '双脚分开与肩同宽站立，正手握住杠铃。 在整个练习过程中保持手臂伸直和背部挺直。 将肩膀尽可能高地抬向耳朵，挤压斜方肌顶部。 保持一会儿，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。', '["双脚分开与肩同宽站立，正手握住杠铃。","在整个练习过程中保持手臂伸直和背部挺直。","将肩膀尽可能高地抬向耳朵，挤压斜方肌顶部。","保持一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0095-dG7tG5y.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-3019', 'bench pull-ups', '背', '自重', '将自己置于与胸部同高的横杆或坚固的水平表面下方。 正手握住杠铃或杠铃表面，握距略宽于肩宽。 双臂完全伸展，身体伸直。 将肩胛骨挤压在一起并弯曲肘部，将胸部拉向杠铃或地面。 继续拉，直到下巴位于杆或表面上方。 有控制地降低自己回到起始位置。 重复所需的重复次数。', '["将自己置于与胸部同高的横杆或坚固的水平表面下方。","正手握住杠铃或杠铃表面，握距略宽于肩宽。","双臂完全伸展，身体伸直。","将肩胛骨挤压在一起并弯曲肘部，将胸部拉向杠铃或地面。","继续拉，直到下巴位于杆或表面上方。","有控制地降低自己回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3019-mExgrF9.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0180', 'cable low seated row', '背', '绳索', '坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。 正手握住手柄，手掌朝下。 保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。 将手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。', '["坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住手柄，手掌朝下。","保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0180-hvV79Si.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0198', 'cable pulldown', '背', '绳索', '调整拉索下拉机，使座椅处于舒适的高度并固定护膝。 坐在座位上，背部挺直，双脚平放在地面上。 正手握住电缆杆，握距略宽于肩宽。 稍微向后倾斜并启动你的核心。 将电缆杆向下拉向胸部，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。 重复所需的重复次数。', '["调整拉索下拉机，使座椅处于舒适的高度并固定护膝。","坐在座位上，背部挺直，双脚平放在地面上。","正手握住电缆杆，握距略宽于肩宽。","稍微向后倾斜并启动你的核心。","将电缆杆向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0198-RVwzP10.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0205', 'cable rear pulldown', '背', '绳索', '调整拉索机，使滑轮处于最高位置。 面向机器坐着，双脚平放在地面上，膝盖稍微弯曲。 正手握住电缆附件，双手之间的距离略大于肩宽。 稍微向后倾斜，保持背部挺直，挺胸。 将电缆附件向下拉向胸部，将肩胛骨挤压在一起。 在动作底部停顿片刻，然后慢慢松开绳索回到起始位置。 重复所需的重复次数。', '["调整拉索机，使滑轮处于最高位置。","面向机器坐着，双脚平放在地面上，膝盖稍微弯曲。","正手握住电缆附件，双手之间的距离略大于肩宽。","稍微向后倾斜，保持背部挺直，挺胸。","将电缆附件向下拉向胸部，将肩胛骨挤压在一起。","在动作底部停顿片刻，然后慢慢松开绳索回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0205-SpsOSXk.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0861', 'cable seated row', '背', '绳索', '坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。 正手握住手柄，保持背部挺直，肩膀放松。 将手柄拉向身体，将肩胛骨挤压在一起。 在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。', '["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住手柄，保持背部挺直，肩膀放松。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0861-fUBheHs.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0220', 'cable shrug', '背', '绳索', '面对电缆机站立，双脚与肩同宽。 正手握住电缆手柄，让手臂垂在身前。 保持手臂伸直，耸肩向耳朵方向向上。 保持收缩一会儿，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。', '["面对电缆机站立，双脚与肩同宽。","正手握住电缆手柄，让手臂垂在身前。","保持手臂伸直，耸肩向耳朵方向向上。","保持收缩一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0220-Eg98Ft9.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0244', 'cable twisting pull', '背', '绳索', '将电缆手柄连接到低滑轮上并面向机器站立。 用左手抓住手柄，离开机器，完全伸展手臂。 双脚分开与肩同宽，膝盖稍微弯曲。 在整个练习过程中保持背部挺直，核心肌群参与其中。 将手柄拉向您的身体，同时将您的躯干向右旋转。 动作结束时挤压背部肌肉。 慢慢回到起始位置，保持绳索的张力。 重复所需的重复次数，然后换边并用右手执行。', '["将电缆手柄连接到低滑轮上并面向机器站立。","用左手抓住手柄，离开机器，完全伸展手臂。","双脚分开与肩同宽，膝盖稍微弯曲。","在整个练习过程中保持背部挺直，核心肌群参与其中。","将手柄拉向您的身体，同时将您的躯干向右旋转。","动作结束时挤压背部肌肉。","慢慢回到起始位置，保持绳索的张力。","重复所需的重复次数，然后换边并用右手执行。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0244-zCgxPbV.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-1324', 'cable upper row', '背', '绳索', '将直杆连接到胸部高度的缆绳机上。 面向机器站立，双脚分开与肩同宽。 正手握住杠铃，双手距离略宽于肩宽。 保持背部挺直，核心肌群参与。 将杠铃拉向上胸部，将肩胛骨挤压在一起。 在动作的最高点停顿片刻。 慢慢地将杠铃释放回起始位置。 重复所需的重复次数。', '["将直杆连接到胸部高度的缆绳机上。","面向机器站立，双脚分开与肩同宽。","正手握住杠铃，双手距离略宽于肩宽。","保持背部挺直，核心肌群参与。","将杠铃拉向上胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢地将杠铃释放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1324-PQStVXH.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-1326', 'chin-up', '背', '自重', '悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。 启动核心肌群，将身体拉向杠铃杆，以胸部为主导。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。', '["悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。","启动核心肌群，将身体拉向杠铃杆，以胸部为主导。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1326-T2mxWqc.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-1327', 'close grip chin-up', '背', '自重', '抓住引体向上杆，手掌朝向自己，双手与肩同宽。 悬挂在杠上，双臂完全伸展，双脚离开地面。 收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。', '["抓住引体向上杆，手掌朝向自己，双手与肩同宽。","悬挂在杠上，双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1327-VnfUNW7.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0327', 'dumbbell incline row', '背', '哑铃', '设置一个 45 度角的上斜凳。 双手各握一个哑铃，坐在长凳上，胸部靠在斜坡上。 充分伸展双臂，让哑铃从肩膀上垂直垂下。 将哑铃拉向胸部，将肩胛骨挤压在一起。 在最高点暂停片刻，然后慢慢将哑铃放回起始位置。 重复所需的重复次数。', '["设置一个 45 度角的上斜凳。","双手各握一个哑铃，坐在长凳上，胸部靠在斜坡上。","充分伸展双臂，让哑铃从肩膀上垂直垂下。","将哑铃拉向胸部，将肩胛骨挤压在一起。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0327-7vG5o25.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0406', 'dumbbell shrug', '背', '哑铃', '双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。 保持手臂伸直，让哑铃垂在身体两侧。 尽可能高地抬高肩膀，就像试图用肩膀触碰耳朵一样。 保持收缩一秒钟，然后慢慢将肩膀放回起始位置。 重复所需的重复次数。', '["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","保持手臂伸直，让哑铃垂在身体两侧。","尽可能高地抬高肩膀，就像试图用肩膀触碰耳朵一样。","保持收缩一秒钟，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0406-NJzBsGJ.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-3292', 'elevator', '背', '自重', '双脚分开与肩同宽站立，膝盖稍微弯曲。 将双手放在臀部或交叉放在胸前。 保持背部挺直，腰部慢慢向前弯曲，将上半身向地面降低。 在底部停顿片刻，然后慢慢抬起上半身回到起始位置。 重复所需的重复次数。', '["双脚分开与肩同宽站立，膝盖稍微弯曲。","将双手放在臀部或交叉放在胸前。","保持背部挺直，腰部慢慢向前弯曲，将上半身向地面降低。","在底部停顿片刻，然后慢慢抬起上半身回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3292-zYmNaoY.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-3295', 'front lever reps', '背', '自重', '正手握住引体向上杆，手掌背向自己。 启动你的核心并将肩胛骨向下拉和向后拉。 保持身体挺直，抬起双腿直至与地面平行。 尽可能长时间地保持这个姿势，目标是 10-20 秒。 慢慢地将双腿放回起始位置。 重复所需的重复次数。', '["正手握住引体向上杆，手掌背向自己。","启动你的核心并将肩胛骨向下拉和向后拉。","保持身体挺直，抬起双腿直至与地面平行。","尽可能长时间地保持这个姿势，目标是 10-20 秒。","慢慢地将双腿放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3295-hbY9wqG.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0466', 'gironda sternum chin', '背', '自重', '面向高杠站立，双脚分开与肩同宽。 向上伸手，正手握住杠铃，握距略宽于肩宽。 悬挂在杠上，双臂完全伸展，身体伸直。 用你的背阔肌和二头肌将你的胸部拉向杠铃杆，以胸骨为主导。 在最高点暂停片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。', '["面向高杠站立，双脚分开与肩同宽。","向上伸手，正手握住杠铃，握距略宽于肩宽。","悬挂在杠上，双臂完全伸展，身体伸直。","用你的背阔肌和二头肌将你的胸部拉向杠铃杆，以胸骨为主导。","在最高点暂停片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0466-IL0JUxR.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0489', 'hyperextension', '背', '自重', '调整过度伸展凳，使大腿上部放在垫子上并且双脚固定。 双臂交叉放在胸前或将双手放在脑后。 将上半身压向地面，同时保持背部挺直。 在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。 重复所需的重复次数。', '["调整过度伸展凳，使大腿上部放在垫子上并且双脚固定。","双臂交叉放在胸前或将双手放在脑后。","将上半身压向地面，同时保持背部挺直。","在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0489-zhMwOwE.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0499', 'inverted row', '背', '自重', '在腰部高度设置一个杠铃或使用悬挂训练器。 面向杠铃或悬吊训练器站立，双脚分开与肩同宽。 正手握住杠铃或手柄，握距略宽于肩宽。 向后倾斜，保持身体挺直，脚后跟着地。 将胸部拉向杠铃或手柄，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。', '["在腰部高度设置一个杠铃或使用悬挂训练器。","面向杠铃或悬吊训练器站立，双脚分开与肩同宽。","正手握住杠铃或手柄，握距略宽于肩宽。","向后倾斜，保持身体挺直，脚后跟着地。","将胸部拉向杠铃或手柄，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0499-bZGHsAZ.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0497', 'inverted row v. 2', '背', '自重', '在史密斯机上在腰部高度设置一根杠铃或使用悬挂训练器。 面向杠铃或悬吊训练器站立，用正手握法抓住它，双手与肩同宽。 双脚向前走，向后倾斜，直到身体呈轻微角度。 保持身体挺直，将胸部向上拉向杠铃或手柄，将肩胛骨挤压在一起。 在最高点暂停片刻，然后慢慢降低回到起始位置。 重复所需的重复次数。', '["在史密斯机上在腰部高度设置一根杠铃或使用悬挂训练器。","面向杠铃或悬吊训练器站立，用正手握法抓住它，双手与肩同宽。","双脚向前走，向后倾斜，直到身体呈轻微角度。","保持身体挺直，将胸部向上拉向杠铃或手柄，将肩胛骨挤压在一起。","在最高点暂停片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0497-uX3sUBz.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0558', 'kipping muscle up', '背', '自重', '首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。 启动你的核心并使用摆动动作来产生动力。 当你向前挥杆时，将胸部拉向杠铃，用背阔肌和二头肌开始动作。 继续向上运动，直到胸部到达杠铃，然后向下推杠铃并伸展手臂，过渡到双臂屈伸姿势。 弯曲手臂并控制下降，将自己放回到起始位置。 重复所需的重复次数。', '["首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。","启动你的核心并使用摆动动作来产生动力。","当你向前挥杆时，将胸部拉向杠铃，用背阔肌和二头肌开始动作。","继续向上运动，直到胸部到达杠铃，然后向下推杠铃并伸展手臂，过渡到双臂屈伸姿势。","弯曲手臂并控制下降，将自己放回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0558-pM07UxU.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-1346', 'kneeling lat stretch', '背', '自重', '跪在地上，膝盖分开与臀部同宽，脚趾向后。 将双臂伸过头顶，手指交叉。 保持背部挺直，慢慢向右侧倾斜，感受左侧背阔肌的拉伸。 保持伸展动作 20-30 秒，然后回到起始位置。 在左侧重复该拉伸动作，向左侧倾斜，感受右侧背阔肌的拉伸。 继续交替进行所需的重复次数。', '["跪在地上，膝盖分开与臀部同宽，脚趾向后。","将双臂伸过头顶，手指交叉。","保持背部挺直，慢慢向右侧倾斜，感受左侧背阔肌的拉伸。","保持伸展动作 20-30 秒，然后回到起始位置。","在左侧重复该拉伸动作，向左侧倾斜，感受右侧背阔肌的拉伸。","继续交替进行所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1346-f38OEuO.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-3418', 'l-pull-up', '背', '自重', '正手握住引体向上杆，握距略宽于肩宽。 双臂完全伸展，身体伸直。 收紧背阔肌和二头肌，将身体拉向杠铃杆，保持肘部靠近身体。 继续拉，直到下巴位于杠铃上方。 在顶部停顿片刻，然后慢慢将身体放回起始位置。 重复所需的重复次数。', '["正手握住引体向上杆，握距略宽于肩宽。","双臂完全伸展，身体伸直。","收紧背阔肌和二头肌，将身体拉向杠铃杆，保持肘部靠近身体。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3418-d1GgzTU.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0573', 'lever back extension', '背', '器械', '调整机器以适合您的身体尺寸和运动范围。 坐在机器上，背部靠在垫子上，双脚固定。 将手放在手柄或握杆上。 启动你的核心并慢慢向前倾斜，让你的背部稍微弯曲。 在底部位置暂停片刻，感觉下背部有拉伸感。 使用背部肌肉，慢慢将躯干抬回到起始位置。 重复所需的重复次数。', '["调整机器以适合您的身体尺寸和运动范围。","坐在机器上，背部靠在垫子上，双脚固定。","将手放在手柄或握杆上。","启动你的核心并慢慢向前倾斜，让你的背部稍微弯曲。","在底部位置暂停片刻，感觉下背部有拉伸感。","使用背部肌肉，慢慢将躯干抬回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0573-rUXfn3R.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0574', 'lever bent over row', '背', '杠铃', '站立，双脚分开与肩同宽，膝盖稍微弯曲。 正手握住杠铃，双手分开略宽于肩宽。 臀部向前弯曲，保持背部挺直，挺胸。 将杠铃拉向下胸部，将肩胛骨挤压在一起。 在顶部停顿片刻，然后慢慢将杠铃放回起始位置。 重复所需的重复次数。', '["站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，双手分开略宽于肩宽。","臀部向前弯曲，保持背部挺直，挺胸。","将杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0574-X3cqyXz.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0579', 'lever front pulldown', '背', '器械', '调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。 正手握住手柄，握距略宽于肩宽。 坐直，胸部抬起，肩膀向后，保持下背部轻微的拱形。 收紧背阔肌，将手柄向下拉向胸部，将肩胛骨挤压在一起。 在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。 重复所需的重复次数。', '["调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。","正手握住手柄，握距略宽于肩宽。","坐直，胸部抬起，肩膀向后，保持下背部轻微的拱形。","收紧背阔肌，将手柄向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0579-7F1DVzn.gif', '', 'hasaneyldrm/exercises-dataset'),
('open-0580', 'lever gripless shrug', '背', '器械', '调整座椅高度并将自己放在杠杆机上。 手掌朝内，抓住手柄，双臂完全伸展。 保持背部挺直，呼气并尽可能抬高肩膀。 保持收缩一会儿，然后吸气并慢慢将肩膀放回起始位置。 重复所需的重复次数。', '["调整座椅高度并将自己放在杠杆机上。","手掌朝内，抓住手柄，双臂完全伸展。","保持背部挺直，呼气并尽可能抬高肩膀。","保持收缩一会儿，然后吸气并慢慢将肩膀放回起始位置。","重复所需的重复次数。"]'::jsonb, '[[0,10],[0,10],[0,10]]'::jsonb, 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0580-f91FwXG.gif', '', 'hasaneyldrm/exercises-dataset'),
